-- (0) DỌN dải id của chính patch này
DELETE FROM `item_template` WHERE `id` BETWEEN 2032 AND 2074;
DELETE FROM `part`          WHERE `id` BETWEEN 2099 AND 2212;
DELETE FROM `head_avatar`   WHERE `head_id` BETWEEN 2099 AND 2212;


-- Ảnh đại diện (avatar) của cải trang: head_avatar tra theo id phần ĐẦU


-- KIỂM TRA
SELECT COUNT(*) AS `vat_pham_moi` FROM `item_template` WHERE `id` BETWEEN 2032 AND 2074;
SELECT COUNT(*) AS `part_moi`     FROM `part`          WHERE `id` BETWEEN 2099 AND 2212;
SELECT COUNT(*) AS `avatar_moi`   FROM `head_avatar`   WHERE `head_id` BETWEEN 2099 AND 2212;
